#!/usr/bin/env python3
"""Builds the Berean AI benchmark suite (cases.jsonl). Evaluation-only; never shipped.

Gold references/Strong's are validated against the real data/*.db by validate_cases.py — this file
only states intent. Topical gold sets are the author's relevance judgement and are marked
human_review=True until a person confirms them.
"""
import json, sys
from pathlib import Path

OUT = Path(__file__).with_name('cases.jsonl')
cases = []

def C(id, section, category, q, *, on=False, deep=False, tab=False, tabref=None, hist=None,
      intent='verses', tools=None, gold=None, gold_any=None, strongs=None, must=None, mustnot=None,
      rules=None, crit=None, fault=None, review=False, platform='mac', static=None, count=None, cover=None):
    mode = ('deep' if deep else 'commentary') if on else ('deep-off' if deep else 'passages')
    hist = hist or []
    cases.append({
        'id': id, 'section': section, 'category': category,
        'commentary_expected': on, 'mode': mode,
        'switches': {'commentary': on, 'deepSearch': deep, 'tabContext': tab},
        'question': q,
        'user_turns': [t[1] for t in hist if t[0] == 'user'] + [q],
        'assistant_turns': [t[1] for t in hist if t[0] == 'assistant'],
        'history': [{'role': r, 'content': c} for r, c in hist],
        'tab': tabref, 'fixture_data': {'fault': fault} if fault else {},
        'expected_intent': intent, 'expected_tools': tools or [],
        'gold_references': gold or [], 'gold_any': gold_any or [], 'gold_strongs': strongs or [],
        'must_include': must or [], 'must_not_include': mustnot or [],
        'expected_count': count, 'cover_groups': cover or [],
        'scoring_rules': rules or [], 'critical_failure_flags': crit or ['fabricated_ref', 'fabricated_strongs'],
        'human_review': review, 'platform': platform, 'static_check': static,
        'multi_turn': bool(hist),
    })

