assert len(ids) == len(set(ids)), 'duplicate ids'
qs = [(c['question'], json.dumps(c['history']), c['fixture_data'].get('fault'), c['switches']['commentary'], c['switches']['deepSearch'], json.dumps(c['tab'])) for c in cases]
